ONLY_CANCELLED = """
CREATE OR REPLACE FUNCTION cbt_an_exam_pin_is_only_ever_cancelled() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            'an_exam_pin_is_only_ever_cancelled: an exam PIN is never deleted; print a new slip to cancel it.'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.cancelled_at IS NOT NULL THEN
        RAISE EXCEPTION
            'an_exam_pin_is_only_ever_cancelled: this exam PIN was cancelled already and does not change again.'
            USING ERRCODE = 'restrict_violation';
    END IF;
    IF NEW.cancelled_at IS NULL
       OR NEW.student_membership_id IS DISTINCT FROM OLD.student_membership_id
       OR NEW.term_id IS DISTINCT FROM OLD.term_id
       OR NEW.class_group_id IS DISTINCT FROM OLD.class_group_id
       OR NEW.digest IS DISTINCT FROM OLD.digest
       OR NEW.issued_by_print_id IS DISTINCT FROM OLD.issued_by_print_id
       OR NEW.issued_by_id IS DISTINCT FROM OLD.issued_by_id
       OR NEW.issued_at IS DISTINCT FROM OLD.issued_at THEN
        RAISE EXCEPTION
            'an_exam_pin_is_only_ever_cancelled: the only change an exam PIN takes is being cancelled.'
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER cbt_an_exam_pin_is_only_ever_cancelled
BEFORE UPDATE OR DELETE ON cbt_exampin
FOR EACH ROW EXECUTE FUNCTION cbt_an_exam_pin_is_only_ever_cancelled();
"""

